def test_a_cerealized_class_belongs_to_the_newest_version_that_binds_it():
    assert v729.CerealizedGameRule.__module__ == "bedrock_protocol.v827"


def test_a_nested_enum_is_shared_by_the_cerealized_class_and_the_plain_one():
    assert v1001.CerealizedInventorySource.InventorySourceFlags is v2225.InventorySource.InventorySourceFlags


def test_encode_rejects_a_cerealized_class_of_another_version():
    with pytest.raises(
        TypeError,
        match=r"^value: <class 'bedrock_protocol\.v975\.CerealizedInventorySource'> is not a type at protocol 1001$",
    ):
        v1001.encode(v975.CerealizedInventorySource(), mode=SerializationMode.CEREAL)


def test_encode_rejects_a_name_the_schema_does_not_hold():
    with pytest.raises(bedrock_protocol.EncodeError, match=r"^CommandOutput\.type: unknown value$"):
        proto.encode(proto.CommandOutput(type=99))


UNKNOWN_PERMISSION = proto.AvailableCommandsPacket(commands=[proto.AvailableCommandsPacket.CommandData(permission=99)])


def test_an_encode_error_is_a_value_error():
    with pytest.raises(ValueError, match="unknown value"):
        proto.encode(proto.CommandOutput(type=99))


def test_an_encode_error_carries_its_reason():
    with pytest.raises(bedrock_protocol.EncodeError, match="unknown value") as caught:
        proto.encode(proto.CommandOutput(type=99))
    assert caught.value.reason == "unknown value"


def test_an_encode_error_carries_the_path_through_a_list_element():
    with pytest.raises(bedrock_protocol.EncodeError, match="unknown value") as caught:
        proto.encode(UNKNOWN_PERMISSION)
    assert caught.value.path == ("commands", 0, "permission")


def test_an_encode_error_message_names_the_nested_field_and_the_list_element():
    with pytest.raises(
        bedrock_protocol.EncodeError,
        match=r"^AvailableCommandsPacket\.commands\[0\]\.permission: unknown value$",
    ):
        proto.encode(UNKNOWN_PERMISSION)


def test_an_encode_error_built_in_python_carries_its_fields():
    error = bedrock_protocol.EncodeError("message", "unknown value", ("a", 1))
    assert (str(error), error.reason, error.path) == ("message", "unknown value", ("a", 1))


def test_an_encode_error_pickles_with_its_fields():
    error = pickle.loads(pickle.dumps(bedrock_protocol.EncodeError("message", "unknown value", ("a", 1))))
    assert (str(error), error.reason, error.path) == ("message", "unknown value", ("a", 1))


def test_every_packet_class_of_a_version_has_an_encoding(protocol):
    assert set(protocol.packets.values()) <= protocol.encodings.keys()


@pytest.mark.parametrize(
    ("version", "since"), [pytest.param(v2225, 729, id="v2225"), pytest.param(v898, 898, id="v898")]
)
def test_an_encoding_is_named_for_the_protocol_that_introduced_it(version, since):
    assert version.encodings[version.TextPacket] == since


def test_the_mode_check_comes_before_the_uninitialized_check():
    cls = v1001.SubChunkPos
    with pytest.raises(TypeError, match=rf"^value: {re.escape(repr(cls))} has no default mode at protocol 1001; "):
        v1001.encode(cls.__new__(cls))


